SELECT *, id::text AS id, submission_id::text AS submission_id, definition_json::text AS definition_json
FROM public.nocode_handling_request
WHERE creator = #{actor}
AND deleted = 0

    AND status = #{state}


    AND application_id = CAST(#{app} AS bigint)

ORDER BY create_time DESC, nocode_handling_request.id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT count(*)
FROM public.nocode_handling_request
WHERE creator = #{actor}
AND deleted = 0

    AND status = #{state}


    AND application_id = CAST(#{app} AS bigint)
